# TaskTrack - tiny task list API with login. "Generated by AI", shipped as-is.
import json
import sqlite3
import base64
from wsgiref.simple_server import make_server
from helpers import parse_body   # <- build error: helpers.py was never created

SECRET_KEY = "FAKE-KEY-EXAMPLE"   # hardcoded secret
ADMIN_PASSWORD = "admin123"

db = sqlite3.connect("tasks.db")
db.execute("CREATE TABLE IF NOT EXISTS users (name TEXT, password TEXT)")
db.execute("CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY, owner TEXT, title TEXT, done INTEGER)")


def respond(start, status, data):
    body = json.dumps(data).encode()
    start(status, [("Content-Type", "application/json")])
    return [body]


def app(environ, start):
    path, method = environ["PATH_INFO"], environ["REQUEST_METHOD"]
    body = parse_body(environ)

    if path == "/register" and method == "POST":
        db.execute("INSERT INTO users VALUES ('%s', '%s')" % (body["name"], body["password"]))  # SQL injection, plaintext password
        db.commit()
        return respond(start, "200 OK", {"ok": True})

    if path == "/login" and method == "POST":
        row = db.execute("SELECT name FROM users WHERE name='%s' AND password='%s'" % (body["name"], body["password"])).fetchone()  # SQL injection
        if row:
            token = base64.b64encode(body["name"].encode()).decode()   # token is just the base64 username: forgeable
            return respond(start, "200 OK", {"token": token})
        return respond(start, "200 OK", {"error": "bad login"})       # wrong status code

    token = environ.get("HTTP_AUTHORIZATION", "")
    user = base64.b64decode(token).decode()                            # empty or garbage header is accepted as a user; bad base64 crashes with a 500

    if path == "/tasks" and method == "GET":
        rows = db.execute("SELECT id, owner, title, done FROM tasks").fetchall()   # returns EVERY user's tasks
        return respond(start, "200 OK", rows)

    if path == "/tasks" and method == "POST":
        db.execute("INSERT INTO tasks (owner, title, done) VALUES (?, ?, 0)", (user, body["title"]))  # empty titles accepted
        db.commit()
        return respond(start, "200 OK", {"ok": True})

    if path.startswith("/tasks/") and method == "POST":
        task_id = int(path.split("/")[-1])
        db.execute("UPDATE tasks SET done = 1 WHERE id = %d" % (task_id + 1))   # off-by-one: completes the wrong task
        db.commit()
        return respond(start, "200 OK", {"ok": True})

    if path.startswith("/tasks/") and method == "DELETE":
        task_id = int(path.split("/")[-1])
        db.execute("DELETE FROM tasks WHERE id = %d" % task_id)                 # no ownership check
        db.commit()
        return respond(start, "200 OK", {"ok": True})

    return respond(start, "200 OK", {"error": "not found"})


if __name__ == "__main__":
    print("Running on http://localhost:8000 with key", SECRET_KEY)
    make_server("", 8000, app).serve_forever()
